description:
Implement `useScrollRestoration` — a hook that saves and restores the scroll position of an element using `sessionStorage`, keyed by a string.

**Example:**
```tsx
const { ref } = useScrollRestoration('sidebar');
return <div ref={ref} style={{ overflowY: 'scroll' }}>...</div>;
// Scroll position is restored on remount
```

starter_code:
import { useRef, useEffect } from 'react';

export function useScrollRestoration(key: string) {
  // your code here
  // return { ref }
}

test_suite:
function mountScroller(key: string) {
  function Scroller() {
    const { ref } = useScrollRestoration(key);
    return <div ref={ref as any} />;
  }
  const view = render(<Scroller />);
  return { el: view.container.firstChild as HTMLElement, unmount: view.unmount };
}

function setScrollTop(el: HTMLElement, value: number) {
  Object.defineProperty(el, 'scrollTop', { writable: true, configurable: true, value });
}

beforeEach(() => {
  sessionStorage.clear();
});

test('returns a ref object', () => {
  const { result } = renderHook(() => useScrollRestoration('page'));
  expect(result.current.ref).toBeDefined();
  expect('current' in result.current.ref).toBe(true);
});

test('restores scrollTop from sessionStorage on mount', () => {
  sessionStorage.setItem('scroll-pos-sidebar', '200');
  const original = Object.getOwnPropertyDescriptor(Element.prototype, 'scrollTop')!;
  let restored: number | undefined;
  Object.defineProperty(Element.prototype, 'scrollTop', {
    configurable: true,
    get: () => restored ?? 0,
    set: (v: number) => { restored = v; },
  });
  try {
    mountScroller('sidebar');
    expect(restored).toBe(200);
  } finally {
    Object.defineProperty(Element.prototype, 'scrollTop', original);
  }
});

test('saves scrollTop to sessionStorage on unmount', () => {
  const { el, unmount } = mountScroller('list');
  setScrollTop(el, 350);
  unmount();
  expect(sessionStorage.getItem('scroll-pos-list')).toBe('350');
});

test('different keys use different sessionStorage entries', () => {
  const nav = mountScroller('nav');
  const content = mountScroller('content');
  setScrollTop(nav.el, 100);
  setScrollTop(content.el, 200);
  nav.unmount();
  content.unmount();
  expect(sessionStorage.getItem('scroll-pos-nav')).toBe('100');
  expect(sessionStorage.getItem('scroll-pos-content')).toBe('200');
});

// __hidden__
test('does not throw when ref is null on unmount', () => {
  const { unmount } = renderHook(() => useScrollRestoration('empty'));
  expect(() => unmount()).not.toThrow();
});

solution:
import { useRef, useEffect } from 'react';

export function useScrollRestoration(key: string) {
  const ref = useRef<HTMLElement>(null);
  const storageKey = `scroll-pos-${key}`;

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const saved = sessionStorage.getItem(storageKey);
    if (saved !== null) el.scrollTop = parseInt(saved, 10);
    return () => {
      sessionStorage.setItem(storageKey, String(el.scrollTop));
    };
  }, [storageKey]);

  return { ref };
}
